def _png_width(path: Path) -> int:
    import struct
    head = path.read_bytes()[:24]
    if head[:8] != b"\x89PNG\r\n\x1a\n":
        return -1
    return struct.unpack(">I", head[16:20])[0]


def patch_app_icon() -> None:
    """Replace every Telegram launcher icon with the telegram-a11y logo (no text).

    - legacy launcher PNGs (ic_launcher*, icon_N_launcher*), adaptive foregrounds (icon*_foreground*)
      and the one PNG background (icon_2_background_sa) in all densities
    - every adaptive-icon background drawable becomes solid black (the old ones were a blue
      gradient plus a white clip ring)
    - the themed (monochrome) icon drawable icon_plane becomes the logo's paper plane
    - the small notification icon (drawable-*/notification.webp) becomes the white paper plane, and the accent
      colour of notifications becomes dark
    """
    import base64
    import io
    import zipfile
    zf = zipfile.ZipFile(io.BytesIO(base64.b64decode("".join(ICON_ASSETS_B64.split()))))
    names = set(zf.namelist())
    dens = ("mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi")
    legacy_px = {48: "mdpi", 72: "hdpi", 96: "xhdpi", 144: "xxhdpi", 192: "xxxhdpi"}
    fg_px = {108: "mdpi", 162: "hdpi", 216: "xhdpi", 324: "xxhdpi", 432: "xxxhdpi"}
    n_png = n_xml = n_notif = 0
    warned = False

    # the library module, plus the standalone module that carries its own legacy ic_launcher_sa.png
    res_roots = [RES]
    sa_res = ROOT.parent / "TMessagesProj_AppStandalone/src/main/res"
    if sa_res.is_dir():
        res_roots.append(sa_res)
    folders = [(d, root / ("mipmap-%s" % d)) for root in res_roots for d in dens]
    for d, folder in folders:
        if not folder.is_dir():
            continue
        for f in sorted(folder.glob("*.png")):
            n = f.name
            if "background_clip" in n:
                continue
            if n.startswith("ic_launcher") or re.fullmatch(r"icon_\d_launcher(_round)?(_sa)?\.png", n):
                kind, table = ("legacyround" if "round" in n else "legacy"), legacy_px
            elif "foreground" in n:
                kind, table = "fg", fg_px
            elif re.fullmatch(r"icon_\d_background(_round)?_sa\.png", n):
                kind, table = "bg", fg_px
            else:
                continue
            w = _png_width(f)
            dd = table.get(w)
            if dd is None:
                dd = d
                if not warned:
                    print("WARN: icon %s has an unexpected width %d; using the size of its folder (%s)" % (n, w, d))
                    warned = True
            asset = "%s-%s.png" % (kind, dd)
            if asset not in names:
                print("WARN: icon asset %s missing" % asset)
                continue
            f.write_bytes(zf.read(asset))
            n_png += 1

    for f in sorted(RES.glob("drawable*/icon_*background*.xml")):
        if "clip" in f.name:
            continue
        f.write_text(ICON_BG_XML, encoding="utf-8")
        n_xml += 1

    mono = RES / "drawable/icon_plane.xml"
    if mono.exists():
        mono.write_text(ICON_PLANE_VECTOR_XML, encoding="utf-8")
        n_xml += 1
    else:
        print("WARN: drawable/icon_plane.xml missing (themed icon)")

    for d in dens:
        f = RES / ("drawable-%s/notification.webp" % d)
        asset = "notif-%s.webp" % d
        if f.exists() and asset in names:
            f.write_bytes(zf.read(asset))
            n_notif += 1

    nc = JAVA / "org/telegram/messenger/NotificationsController.java"
    if nc.exists():
        t = nc.read_text(encoding="utf-8")
        if "0xff11acfa" in t:
            nc.write_text(t.replace("0xff11acfa", NOTIFICATION_COLOR), encoding="utf-8")
            print("notification colour OK")
        elif NOTIFICATION_COLOR in t:
            print("notification colour already patched")
        else:
            print("WARN: notification colour 0xff11acfa not found in NotificationsController.java")
    print("App icon OK (%d launcher PNGs, %d xml drawables, %d notification icons)" % (n_png, n_xml, n_notif))


def patch_app_name() -> None:
    p = RES / "values/strings.xml"
    if p.exists():
        _set_string(p, "AppName", EN_NAME)
        _set_string(p, "AppNameBeta", EN_NAME)
    for rel in ("values-fa/strings.xml", "values-fa-rIR/strings.xml"):
        _set_string(RES / rel, "AppName", FA_NAME)
        _set_string(RES / rel, "AppNameBeta", FA_NAME)
    print("AppName OK")



