        "                child.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);\n"
        "            }\n"
        "        } else {\n"
        "            for (java.util.Map.Entry<View, Integer> e : a11ySiblingModes.entrySet()) {\n"
        "                if (e.getKey() != null) {\n"
